  void HandleOdometry(const amr_dispatcher_core::chassis::ChassisOdometryPacket& odometry,
                      const rclcpp::Time& stamp);
  void HandleState(const amr_dispatcher_core::chassis::ChassisStatePacket& state);
  void PublishBatteryState(
      const amr_dispatcher_core::chassis::ChassisOdometryPacket& odometry,
      const rclcpp::Time& stamp);
  // 0xA1 与 0xA2 共用的电压发布路径（共用节流状态，见实现处的注释）。
  void PublishBatteryVoltage(double voltage, const rclcpp::Time& stamp);
  // T2：故障位进安全链。锁存语义：置位后链路判不可信，收到无故障帧才解除。
  void UpdateChassisFaultState(bool fault, const char* source);

  rclcpp::Subscription<geometry_msgs::msg::Twist>::SharedPtr cmd_vel_sub_;
  rclcpp::Publisher<nav_msgs::msg::Odometry>::SharedPtr odom_pub_;
  rclcpp::Publisher<sensor_msgs::msg::BatteryState>::SharedPtr battery_pub_;
  // 阶段 4b：原先这里还有 health_pub_（节点自建的 rosidl 发布器）。
  // 已删除并收进 health_proto_pub_——留着它就会出现两个 rosidl 发布器
  // 指向同一话题，而「只发 proto」的开关也因此不能真正生效。
  //
  // 阶段 2 双发：与 rosidl 侧同源同帧的 protobuf 副本（话题 /chassis/link_health_proto）。
  // 用 unique_ptr 是因为 ProtoDualPublisher 必须以「解析后的最终话题名」构造，
  // 而该名字在构造函数体内才算出（依赖 vehicle_id 与覆盖参数）。
  std::unique_ptr<ProtoDualPublisher<
      amr_dispatcher_interfaces::msg::ChassisLinkHealth,
      amr_dispatcher::proto::ChassisLinkHealth>> health_proto_pub_;
  rclcpp::Publisher<std_msgs::msg::Bool>::SharedPtr heartbeat_pub_;
  std::unique_ptr<tf2_ros::TransformBroadcaster> tf_broadcaster_;

  rclcpp::TimerBase::SharedPtr poll_timer_;
  rclcpp::TimerBase::SharedPtr health_timer_;

  std::unique_ptr<amr_dispatcher_core::chassis::BackendDegradationController> backend_ctrl_;
  amr_dispatcher_core::chassis::ChassisPacketStream text_stream_;
  amr_dispatcher_core::chassis::MickBinaryPacketStream binary_stream_;
  // T3：下行序号 + 命令送达率。只在 mick_binary 协议下推进 seq；
  // 文本协议的 MCU 不回显，统计保持“无回显”状态（送达率 0、不参与健康判定）。
  amr_dispatcher_core::chassis::CommandDeliveryTracker delivery_tracker_;

  // 链路协议：text（ODOM/STATE 文本行）| mick_binary（0xAE 0xEA ... 0xEF 0xFE 帧）。
  // 必须与 ChassisBackendConfig.protocol 一致，否则下行编码与上行解析不匹配。
  std::string protocol_ = "text";
  bool binary_protocol_ = false;

  // 上行帧超时：串口句柄还在但 MCU 已停发时，链路属于"假活"。
  // PublishHealth 不再无条件置心跳，改为以此为依据，see ReadPollLoop。
  std::chrono::milliseconds odom_timeout_{300};
  std::chrono::steady_clock::time_point last_odom_stamp_{};
  bool has_odom_packet_ = false;
  bool link_alive_ = false;
  // 最近一次上报电压（V），0 表示从未收到；用于 battery_state 变化率节流。
  double last_battery_voltage_ = 0.0;
  // 保底发布节拍：电压长期不变时仍定期上报，避免电池话题静默。
  std::chrono::steady_clock::time_point last_battery_stamp_{};
  // 12V 台架默认值：满=12.6V（6 串 4.2V 折算区间不对时按单体配置调整），空=11.0V。
  // 24V 系统改用 25.2 / 21.0 即可，两个值都可从参数覆盖。
  double battery_full_voltage_ = 12.6;
  double battery_empty_voltage_ = 11.0;
  bool fault_reported_ = false;
  // T2：底盘上报的故障锁存。置位后链路判为不可信（心跳下沉），直到
  // 收到一帧无故障的上行帧才自动解除。锁存是必需的：0xA2 只在状态变化时
  // 发送，若只在“收到 fault 帧的那一拍”降级，下一拍就恢复了。
  bool chassis_fault_latched_ = false;

  std::string odom_frame_id_ = "odom";
  std::string base_frame_id_ = "base_link";
  bool publish_tf_ = true;
  // B1：最近一次收到 /cmd_vel_safe 的时刻，用于指令龄超时零速兜底
  std::chrono::steady_clock::time_point last_cmd_stamp_{};
  bool has_cmd_stamp_ = false;
  // B1：指令龄超时阈值（毫秒），ReadPollLoop 超时后主动写零帧
  std::chrono::milliseconds cmd_stale_timeout_{500};
  // B1：本轮失联零速是否已告警/已写帧（恢复后重置，避免每次 poll 刷屏）
  bool stale_zero_active_ = false;

  // ---- P0.6 / A4：per-vehicle 话题与 TF 隔离 ----
  // vehicle_id 空 = 单车兼容模式（话题名与 frame 名逐字不变）；
  // 非空 = 话题按 {vid} 派生，TF frame 按 {vid}/odom、{vid}/base_link 派生。
  std::string vehicle_id_;
  std::string cmd_vel_topic_{"/cmd_vel_safe"};
  std::string odom_topic_{"/odom"};
  std::string link_health_topic_{"/chassis/link_health"};
  std::string battery_topic_{"/battery_state"};
  std::string heartbeat_topic_{"/safety/heartbeat/chassis_driver"};

  // 阶段 2：proto 双发总开关（参数 proto_dual_publish）。
  // 在构造函数最前面声明并读出，后续所有双发器都引用它。
  bool proto_dual_publish_{true};
  // 阶段 4b：rosidl 侧开关（参数 proto_rosidl_publish，默认开）。
  // false = 只发 *_proto，DDS 里不再有 /chassis/link_health。
  bool proto_rosidl_publish_{true};
};

}  // namespace amr_dispatcher_ros

#include <chrono>
#include <memory>
#include <string>
#include <vector>

#include <rclcpp/rclcpp.hpp>

#include "amr_dispatcher_core/chassis/link_quality.hpp"
#include "amr_dispatcher_interfaces/msg/chassis_link_health.hpp"
#include "amr_dispatcher_proto_bridge/proto_dual_subscriber.hpp"
#include "amr_dispatcher_ros/proto_dual_publisher.hpp"

using namespace std::chrono_literals;

namespace amr_dispatcher_ros {

class LinkHealthPublisherNode : public rclcpp::Node {
 public:
  explicit LinkHealthPublisherNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : rclcpp::Node("link_health_publisher_node", options) {
    declare_parameter("publish_rate_hz", 2.0);
    declare_parameter("watched_topics", std::vector<std::string>{"/chassis/link_health"});
    // 阶段 2 双发总开关（默认开）。关闭只停 proto 侧。
    declare_parameter("proto_dual_publish", true);
    // 阶段 4b：rosidl 侧开关（默认开）。设为 false 后本节点只发布 *_proto，
    // DDS 里不再出现 /system/aggregated_link_health——这就是「切流」。
    // 与 proto_dual_publish 相互独立：两个都关 = 什么都不发（只用于测试）。
    declare_parameter("proto_rosidl_publish", true);
    // 阶段 3 双订阅总开关（默认关）。开启后 watched_topics 的每一项都改从
    // "<topic>_proto" 读取，适配器内部反投影回 rosidl 后交给同一段回调。
    //
    // 每项必须是**已解析的最终话题名**：发布端是 ResolveVehicleTopic 之后再
    // 追加 _proto 后缀，订阅端若传原始模板名就会派生出错误的话题名，
    // 表现为「订阅成功但永远收不到」。
    declare_parameter("proto_dual_subscribe", false);
    const bool proto_dual_publish = get_parameter("proto_dual_publish").as_bool();
    const bool proto_rosidl_publish = get_parameter("proto_rosidl_publish").as_bool();
    const bool proto_dual_subscribe = get_parameter("proto_dual_subscribe").as_bool();

    auto topics = get_parameter("watched_topics").as_string_array();
    subs_.reserve(topics.size());
    for (const auto& t : topics) {
      // 阶段 3：每项都可切到 proto 话题。用 make_unique 存放：适配器持有
      // 订阅句柄，放进 unique_ptr 后 vector 扩容不会搬动对象本身，
      // 订阅生命周期与 vector 同寿命。
      subs_.push_back(std::make_unique<amr_dispatcher_proto_bridge::ProtoDualSubscriber<
          amr_dispatcher_interfaces::msg::ChassisLinkHealth,
          amr_dispatcher::proto::ChassisLinkHealth>>(
          this, t, 10, proto_dual_subscribe,
          [this, t](const amr_dispatcher_interfaces::msg::ChassisLinkHealth::SharedPtr msg) {
            latest_health_[t] = *msg;
          }));
    }
    if (proto_dual_subscribe && !subs_.empty()) {
      RCLCPP_INFO(get_logger(),
                  "link health source: proto topics (*_proto), first='%s'",
                  subs_.front()->proto_topic().c_str());
    }

    // 阶段 2 双发：/system/aggregated_link_health_proto。
    //
    // 注意这条话题**不是** per-vehicle 派生的（它是全局聚合视图，由本节点把
    // 多车健康合成一条），所以这里直接传字面量，不经 ResolveVehicleTopic。
    //
    // 阶段 4b：rosidl 侧也收进来了——原先这里是 create_publisher 建 agg 的
    // rosidl 发布器 + 双发器只管 proto，两套句柄让「只发一侧」无法用参数表达。
    // 现在双发器是唯一出口，PublishAll 负责两侧投递。
    aggregated_proto_pub_ = std::make_unique<ProtoDualPublisher<
        amr_dispatcher_interfaces::msg::ChassisLinkHealth,
        amr_dispatcher::proto::ChassisLinkHealth>>(
        this, "/system/aggregated_link_health", 10, proto_dual_publish,
        proto_rosidl_publish);
    if (aggregated_proto_pub_->enabled()) {
      RCLCPP_INFO(get_logger(), "proto dual-publish enabled: %s",
                  aggregated_proto_pub_->proto_topic().c_str());
    }
    if (!aggregated_proto_pub_->rosidl_enabled()) {
      // 显式告警：切流之后若还有第三方订阅 rosidl 话题，它们会静默地收不到
      // 任何东西——DDS 不会报错，订阅端也不会超时退出，只会一直等。
      RCLCPP_WARN(get_logger(),
                  "rosidl 侧已关闭，仅发布 proto 话题 %s；"
                  "请确认没有订阅方仍依赖 %s",
                  aggregated_proto_pub_->proto_topic().c_str(),
                  aggregated_proto_pub_->rosidl_topic().c_str());
    }

    const double rate = get_parameter("publish_rate_hz").as_double();
    timer_ = create_wall_timer(
        std::chrono::duration<double>(1.0 / rate),
        std::bind(&LinkHealthPublisherNode::PublishAggregated, this));

    RCLCPP_INFO(get_logger(), "LinkHealthPublisherNode started, monitoring %zu topics", topics.size());
  }

 private:
  void PublishAggregated() {
    if (latest_health_.empty()) return;

    amr_dispatcher_interfaces::msg::ChassisLinkHealth agg;
    agg.header.stamp = now();
    agg.backend_name = "aggregated";
    agg.is_healthy = true;

    double max_loss = 0.0;
    double max_lat = 0.0;
    double sum_avg_lat = 0.0;
    // T3：命令送达率取**最差**的一路（任一台车的命令在丢，都该被看见），
    // 只要有一路适用就适用；全部为 -1（文本协议/未回显）时保持 -1。
    double worst_delivery = -1.0;
    std::uint64_t sum_cmd_sent = 0;
    std::uint64_t sum_cmd_delivered = 0;

    for (const auto& [name, h] : latest_health_) {
      agg.frames_total += h.frames_total;
      agg.frames_success += h.frames_success;
      agg.frames_lost += h.frames_lost;
      agg.frames_crc_error += h.frames_crc_error;
      if (h.loss_rate > max_loss) max_loss = h.loss_rate;
      if (h.max_latency_ms > max_lat) max_lat = h.max_latency_ms;
      sum_avg_lat += h.avg_latency_ms;
      if (!h.is_healthy) agg.is_healthy = false;
      if (h.command_delivery_rate >= 0.0) {
        if (worst_delivery < 0.0 || h.command_delivery_rate < worst_delivery) {
          worst_delivery = h.command_delivery_rate;
        }
      }
      sum_cmd_sent += h.commands_sent;
      sum_cmd_delivered += h.commands_delivered;
    }
    agg.command_delivery_rate = worst_delivery;
    agg.commands_sent = sum_cmd_sent;
    agg.commands_delivered = sum_cmd_delivered;

    agg.loss_rate = agg.frames_total > 0
                        ? static_cast<double>(agg.frames_lost) / static_cast<double>(agg.frames_total)
                        : 0.0;
    agg.avg_latency_ms = sum_avg_lat / static_cast<double>(latest_health_.size());
    agg.max_latency_ms = max_lat;

    if (agg.loss_rate >= 0.3) {
      agg.tier = "CRITICAL";
    } else if (agg.loss_rate >= 0.15) {
      agg.tier = "DEGRADED";
    } else if (agg.is_healthy) {
      agg.tier = "HEALTHY";
    } else {
      agg.tier = "UNKNOWN";
    }

    // 阶段 2 双发 + 阶段 4b 收口：从同一个 agg 同时投递两侧。
    // 聚合逻辑（最差送达率、求和计数器等）只有一份实现，不会出现
    // 「rosidl 侧改了聚合口径、proto 侧没跟上」的漂移；
    // 「发不发 rosidl」也由构造参数统一决定，调用点不再有 if。
    if (aggregated_proto_pub_) {
      aggregated_proto_pub_->PublishAll(agg);
    }
  }

  // 阶段 3：双订阅容器。vector 可以容纳移动-only 元素，正好匹配
  // 「watched_topics 运行时长度不定」这个既有约束。
  std::vector<std::unique_ptr<amr_dispatcher_proto_bridge::ProtoDualSubscriber<
      amr_dispatcher_interfaces::msg::ChassisLinkHealth,
      amr_dispatcher::proto::ChassisLinkHealth>>> subs_;
  // 阶段 4b：rosidl 与 proto 两侧都由双发器持有，原先独立的
  // aggregated_pub_（rclcpp::Publisher）已删除——留着它就会有两个
  // rosidl 发布器指向同一话题，切流参数也就不再是真开关。
  std::unique_ptr<ProtoDualPublisher<
      amr_dispatcher_interfaces::msg::ChassisLinkHealth,
      amr_dispatcher::proto::ChassisLinkHealth>> aggregated_proto_pub_;
  rclcpp::TimerBase::SharedPtr timer_;
  std::unordered_map<std::string, amr_dispatcher_interfaces::msg::ChassisLinkHealth> latest_health_;
};

}  // namespace amr_dispatcher_ros

int main(int argc, char* argv[]) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared<amr_dispatcher_ros::LinkHealthPublisherNode>();
  rclcpp::spin(node);
  rclcpp::shutdown();
  return 0;
}

// 双发发布器（lifecycle 节点版）。
//
// 与 proto_dual_publisher.hpp 的唯一差别：proto 侧用
// rclcpp_lifecycle::LifecyclePublisher 而不是 rclcpp::Publisher，因此
// 需要节点在 on_activate / on_deactivate 里显式调用 Activate() / Deactivate()。
//
// ============================================================================
// 为什么这个差别不能省
// ============================================================================
// dispatcher_node 的状态发布器是 LifecyclePublisher：节点处于 unconfigured /
// inactive 时，rosidl 侧的 publish 是**静默空操作**（连消息都不序列化）。
// 如果 proto 侧用的是普通 Publisher，那么节点 inactive 期间会出现
// 「rosidl 不发、proto 照发」——订阅方看到一条有数据流的 proto 话题，
// 会认为调度器在正常工作；一致性检查器也会报 proto 多帧。
// 这类偏差只在运行时可见，编译期和常规单测都抓不到。
//
// 所以 lifecycle 节点的 proto 侧必须逐条跟随 rosidl 侧的激活态，
// 本类把 on_activate/on_deactivate 的转发封进来，节点侧只需成对调用。
#ifndef AMR_DISPATCHER_ROS__PROTO_LIFECYCLE_DUAL_PUBLISHER_HPP_
#define AMR_DISPATCHER_ROS__PROTO_LIFECYCLE_DUAL_PUBLISHER_HPP_

#include <memory>
#include <string>

#include <rclcpp_lifecycle/lifecycle_node.hpp>

#include "amr_dispatcher_ros/proto_dual_publisher.hpp"

namespace amr_dispatcher_ros
{

/// lifecycle 版双发器：proto 侧是 LifecyclePublisher，需显式激活。
///
/// 构造后 proto 发布器处于未激活态，与 rosidl 侧一致；节点 on_activate 时
/// 调 Activate()，on_deactivate 时调 Deactivate()，on_cleanup 时释放本对象。
template<typename RosidlMsgT, typename ProtoT>
class ProtoLifecycleDualPublisher
{
public:
  /// \param node       必须是 LifecycleNode（create_publisher 才会返回 LifecyclePublisher）
  /// \param rosidl_name 已解析的 rosidl 话题名（proto 名由它派生）
  /// \param qos_depth   QoS 深度，必须与 rosidl 侧一致
  /// \param enabled     proto 侧总开关，false 时连 proto 发布器都不创建
  /// \param rosidl_enabled rosidl 侧开关（阶段 4b）。**默认 true**，
  ///                    既有调用点行为逐位不变。false 时连 rosidl 发布器都不创建，
  ///                    DDS 里不会留下一个没人订阅的 rosidl 话题。
  ProtoLifecycleDualPublisher(
    rclcpp_lifecycle::LifecycleNode * node, const std::string & rosidl_name,
    std::size_t qos_depth, bool enabled, bool rosidl_enabled = true)
  : rosidl_topic_(rosidl_name),
    proto_topic_(ProtoTopicName(rosidl_name)),
    enabled_(enabled),
    rosidl_enabled_(rosidl_enabled)
  {
    if (rosidl_enabled_) {
      rosidl_pub_ = node->create_publisher<RosidlMsgT>(
        rosidl_topic_, rclcpp::QoS(qos_depth));
    }
    if (!enabled_) {
      return;
    }
    pub_ = node->create_publisher<ProtoT>(proto_topic_, rclcpp::QoS(qos_depth));
  }

  bool enabled() const {return static_cast<bool>(pub_);}

  /// rosidl 侧是否在发布（阶段 4b）。false 表示「只留 proto」。
  bool rosidl_enabled() const {return static_cast<bool>(rosidl_pub_);}

  const std::string & proto_topic() const {return proto_topic_;}
  const std::string & rosidl_topic() const {return rosidl_topic_;}

  /// 同时发布两侧，激活态由两个 LifecyclePublisher 各自管理。
  ///
  /// 这是过渡期结束后各节点应当使用的**唯一**入口。
  bool PublishAll(const RosidlMsgT & msg)
  {
    bool published = false;
    if (rosidl_pub_) {
      rosidl_pub_->publish(msg);
      published = true;
    }
    if (Publish(msg)) {
      published = true;
    }
    return published;
  }

  /// 从 rosidl 消息投影并发布。未启用时为空操作。
  ///
  /// 未激活时由 LifecyclePublisher 自行丢弃并打印一次日志——与 rosidl 侧
  /// 的行为逐位一致，因此调用方不需要额外判断激活态。
  bool Publish(const RosidlMsgT & msg)
  {
    if (!pub_) {
      return false;
    }
    ProtoT proto_msg;
    ProjectRosidlToProto(msg, &proto_msg);
    pub_->publish(proto_msg);
    return true;
  }

  /// 与 rosidl 侧 on_activate 成对调用。
  void Activate()
  {
    // 两侧都要激活：rosidl 侧在 4b 之前一直由节点自己管理，收进来之后
    // 必须同样跟随，否则会出现「proto 激活了、rosidl 没激活」的镜像问题
    // ——正是本类头部注释描述的那个偏差的反向版本。
    if (rosidl_pub_) {
      rosidl_pub_->on_activate();
    }
    if (pub_) {
      pub_->on_activate();
    }
  }

  /// 与 rosidl 侧 on_deactivate 成对调用。
  void Deactivate()
  {
    if (rosidl_pub_) {
      rosidl_pub_->on_deactivate();
    }
    if (pub_) {
      pub_->on_deactivate();
    }
  }

private:
  std::string rosidl_topic_;
  std::string proto_topic_;
  bool enabled_{false};
  bool rosidl_enabled_{true};
  typename rclcpp_lifecycle::LifecyclePublisher<ProtoT>::SharedPtr pub_;
  /// rosidl 侧发布器。仅在 rosidl_enabled 为 true 时创建。
  typename rclcpp_lifecycle::LifecyclePublisher<RosidlMsgT>::SharedPtr rosidl_pub_;
};

}  // namespace amr_dispatcher_ros

#endif  // AMR_DISPATCHER_ROS__PROTO_LIFECYCLE_DUAL_PUBLISHER_HPP_

input.old_string:
cmd_vel_pub_->publish(cmd);
