}

toolUseResult.oldString:
cmd_vel_pub_->publish(cmd);
error_pub_->publish(err_msg);
// 阶段 2 双发：从同一个 err_msg 投影，保证两路逐字段一致。
if (error_proto_pub_) {
  error_proto_pub_->Publish(err_msg);
}

toolUseResult.newString:
cmd_vel_pub_->publish(cmd);
