// 不会出现「两侧都关却报『仅发布 proto』」这种误导（见 LogStatus）。
// 三个实例的文案合并成一行，否则启动日志里会出现三条重复的
// 「双发已启用」——调度器本就有大量启动输出，能省则省。
if (state_proto_pub_ && event_proto_pub_ && topology_proto_pub_) {
  const bool any_proto = state_proto_pub_->enabled();
  const bool any_rosidl = state_proto_pub_->rosidl_enabled();
  if (any_proto && any_rosidl) {
    RCLCPP_INFO(get_logger(), "双发已启用：%s %s %s（rosidl 侧同步）",
                state_proto_pub_->proto_topic().c_str(),
                event_proto_pub_->proto_topic().c_str(),
                topology_proto_pub_->proto_topic().c_str());
  } else if (!any_proto && !any_rosidl) {
    RCLCPP_ERROR(get_logger(),
                 "两侧都已关闭：dispatcher 既不发布 rosidl 也不发布 proto "
                 "（state/events/topology 全静默）。此组合仅用于测试，"
                 "请检查 proto_dual_publish / proto_rosidl_publish");
  } else if (any_proto) {
    RCLCPP_WARN(get_logger(),
                "rosidl 侧已关闭，仅发布 proto 话题 %s %s %s；"
                "请确认没有订阅方仍依赖 %s %s %s",
                state_proto_pub_->proto_topic().c_str(),
                event_proto_pub_->proto_topic().c_str(),
                topology_proto_pub_->proto_topic().c_str(),
                state_proto_pub_->rosidl_topic().c_str(),
                event_proto_pub_->rosidl_topic().c_str(),
                topology_proto_pub_->rosidl_topic().c_str());
  } else {
    RCLCPP_INFO(get_logger(),
                "proto 侧已关闭，仅发布 rosidl 话题 %s %s %s",
                state_proto_pub_->rosidl_topic().c_str(),
                event_proto_pub_->rosidl_topic().c_str(),
                topology_proto_pub_->rosidl_topic().c_str());
  }
}

