140	  ProtoDualPublisher(
141	    rclcpp::Node * node, const std::string & rosidl_name, std::size_t qos_depth, bool enabled,
142	    bool rosidl_enabled = true)
143	  : rosidl_topic_(rosidl_name),
144	    proto_topic_(ProtoTopicName(rosidl_name)),
145	    enabled_(enabled),
146	    rosidl_enabled_(rosidl_enabled)
147	  {
148	    // rosidl 侧：阶段 4b 之前由各节点自己 create_publisher，现在收进来，
149	    // 让「发不发 rosidl」成为一个参数而不是散落在 7 个节点里的 if。
150	    if (rosidl_enabled_) {
151	      rosidl_pub_ = node->create_publisher<RosidlMsgT>(rosidl_topic_, rclcpp::QoS(qos_depth));
152	    }
153	    if (!enabled_) {
154	      return;
155	    }
156	    pub_ = node->create_publisher<ProtoT>(proto_topic_, rclcpp::QoS(qos_depth));
157	  }
158	
159	  /// 是否真正启用了 proto 侧。调用方用它决定是否值得构造 proto 消息。
160	  bool enabled() const {return static_cast<bool>(pub_);}
161	
162	  /// rosidl 侧是否在发布（阶段 4b）。false 表示「只留 proto」。
163	  bool rosidl_enabled() const {return static_cast<bool>(rosidl_pub_);}
