182	        rosidl_topic_.c_str(), proto_topic_.c_str());
183	      return;
184	    }
185	    if (rosidl_pub_) {
186	      RCLCPP_INFO(logger, "proto 侧已关闭，仅发布 rosidl 话题 %s",
187	        rosidl_topic_.c_str());
188	      return;
189	    }
