20	      : rclcpp::Node("link_health_publisher_node", options) {
21	    declare_parameter("publish_rate_hz", 2.0);
22	    declare_parameter("watched_topics", std::vector<std::string>{"/chassis/link_health"});
23	    // 阶段 2 双发总开关（默认开）。关闭只停 proto 侧。
24	    declare_parameter("proto_dual_publish", true);
25	    // 阶段 4b：rosidl 侧开关（默认开）。设为 false 后本节点只发布 *_proto，
26	    // DDS 里不再出现 /system/aggregated_link_health——这就是「切流」。
27	    // 与 proto_dual_publish 相互独立：两个都关 = 什么都不发（只用于测试）。
28	    declare_parameter("proto_rosidl_publish", true);
29	    // 阶段 3 双订阅总开关（默认关）。开启后 watched_topics 的每一项都改从
30	    // "<topic>_proto" 读取，适配器内部反投影回 rosidl 后交给同一段回调。
31	    //
32	    // 每项必须是**已解析的最终话题名**：发布端是 ResolveVehicleTopic 之后再
33	    // 追加 _proto 后缀，订阅端若传原始模板名就会派生出错误的话题名，
34	    // 表现为「订阅成功但永远收不到」。
35	    declare_parameter("proto_dual_subscribe", false);
36	    const bool proto_dual_publish = get_parameter("proto_dual_publish").as_bool();
37	    const bool proto_rosidl_publish = get_parameter("proto_rosidl_publish").as_bool();
38	    const bool proto_dual_subscribe = get_parameter("proto_dual_subscribe").as_bool();
39	
40	    auto topics = get_parameter("watched_topics").as_string_array();
41	    subs_.reserve(topics.size());
42	    for (const auto& t : topics) {
43	      // 阶段 3：每项都可切到 proto 话题。用 make_unique 存放：适配器持有
