107	TEST(RoundTrip, ChassisLinkHealth) {
108	  ChassisLinkHealth in;
109	  in.header = MakeHeader();
110	  in.backend_name = "serial";
111	  in.tier = "DEGRADED";
112	  in.frames_total = 1000u;
113	  in.frames_success = 900u;
114	  in.frames_lost = 100u;
115	  in.frames_crc_error = 5u;
116	  in.loss_rate = 0.1;
117	  in.avg_latency_ms = 12.5;
118	  in.max_latency_ms = 80.0;
119	  in.is_healthy = false;
120	  // 刻意用 -1 哨兵：这是三处有损点里最容易在往返中被抹平的一个。
121	  in.command_delivery_rate = -1.0;
122	  in.commands_sent = 500u;
123	  in.commands_delivered = 485u;
124	
125	  amr_dispatcher::proto::ChassisLinkHealth p;
126	  amr_dispatcher_ros::proto_projection::ProjectChassisLinkHealth(in, &p);
127	
128	  ChassisLinkHealth out;
129	  amr_dispatcher_proto_bridge::reverse_projection::RestoreChassisLinkHealth(p, &out);
130	
131	  ExpectHeaderEq(in.header, out.header);
132	  EXPECT_EQ(in.backend_name, out.backend_name);
133	  EXPECT_EQ(in.tier, out.tier);
134	  EXPECT_EQ(in.frames_total, out.frames_total);
135	  EXPECT_EQ(in.frames_success, out.frames_success);
136	  EXPECT_EQ(in.frames_lost, out.frames_lost);
137	  EXPECT_EQ(in.frames_crc_error, out.frames_crc_error);
138	  EXPECT_DOUBLE_EQ(in.loss_rate, out.loss_rate);
139	  EXPECT_DOUBLE_EQ(in.avg_latency_ms, out.avg_latency_ms);
140	  EXPECT_DOUBLE_EQ(in.max_latency_ms, out.max_latency_ms);
141	  EXPECT_EQ(in.is_healthy, out.is_healthy);
142	  // -1 -> valid=false -> -1：往返必须回到 -1，不能是 0.0。
143	  EXPECT_DOUBLE_EQ(out.command_delivery_rate, -1.0);
144	  EXPECT_EQ(in.commands_sent, out.commands_sent);
145	  EXPECT_EQ(in.commands_delivered, out.commands_delivered);
146	}
