394	// ---------------------------------------------------------------------------
395	// 话题名派生：发布端与订阅端必须派生出同一个名字
396	// ---------------------------------------------------------------------------
397	// 两侧各有一份 kProtoTopicSuffix（bridge 不能依赖 ros 包，见两处头文件
398	// 注释）。漂移的后果是「订阅成功但永远收不到」——DDS 不报错，只是没有
399	// 匹配的发布者，属于最难现场定位的一类故障。这个用例是唯一的守卫。
400	TEST(RoundTrip, ProtoTopicNameParityAcrossPackages) {
401	  const std::vector<std::string> topics = {
402	    "/chassis/link_health",
403	    "/system/aggregated_link_health",
404	    "/dispatcher/state",
405	    "/dispatcher/events",
406	    "/dispatcher/topology_state",
407	    "/safety/state",
408	    "/tracking/error",
409	    "/tracking/error/amr_01",
410	  };
411	  for (const auto & t : topics) {
412	    EXPECT_EQ(
413	      amr_dispatcher_ros::ProtoTopicName(t),
414	      amr_dispatcher_proto_bridge::ProtoTopicName(t))
415	      << "topic name drift for " << t;
416	  }
417	}
